<template><view class="p"><view class="nav"><text @click="back">‹</text><text>监控任务</text><text @click="load">⟳</text></view><scroll-view scroll-y class="list"><view class="card" v-for="t in tasks" :key="t.taskKey"><view class="top"><text class="name">{{t.taskName||t.taskKey}}</text><switch :checked="!!t.enabled" @change="toggle(t,$event)"/></view><text class="desc">{{t.category||'-'}} · {{t.cron||'-'}}</text><text class="desc">{{t.lastResult||'暂无执行结果'}}</text><button @click="run(t)">立即执行</button></view><view v-if="!tasks.length" class="hint">暂无任务</view></scroll-view></view></template>
<script setup lang="ts">import{onMounted,ref}from'vue';import{getTasks,toggleTask,runTask}from'@/api/scheduledTasks';const tasks=ref<any[]>([]);async function load(){try{const r:any=await getTasks({page:1,size:100});tasks.value=Array.isArray(r)?r:(r?.records||[])}catch(e:any){uni.showToast({title:e?.message||'加载失败',icon:'none'})}}async function toggle(t:any,e:any){try{const enabled=!!e.detail.value;await toggleTask(t.taskKey,enabled);t.enabled=enabled}catch(err:any){uni.showToast({title:err?.message||'操作失败',icon:'none'})}}async function run(t:any){try{await runTask(t.taskKey);uni.showToast({title:'已触发',icon:'success'});load()}catch(e:any){uni.showToast({title:e?.message||'执行失败',icon:'none'})}}function back(){uni.navigateBack({fail:()=>uni.switchTab({url:'/pages/profile/index'})})}onMounted(load)</script><style scoped lang="scss">.p{min-height:100vh;background:#f5f5f7}.nav{height:88rpx;background:#fff;display:flex;align-items:center;justify-content:space-between;padding:0 24rpx;font-size:32rpx;font-weight:700}.nav text:first-child{font-size:48rpx;color:#6b7280}.nav text:last-child{font-size:34rpx;color:#4f46e5}.list{height:calc(100vh - 88rpx);padding:24rpx}.card{background:#fff;border-radius:24rpx;padding:24rpx;margin-bottom:16rpx}.top{display:flex;justify-content:space-between;align-items:center}.name{font-weight:800;color:#111827}.desc{display:block;color:#6b7280;font-size:24rpx;margin-top:10rpx}button{margin-top:16rpx;background:#4f46e5;color:#fff;border-radius:32rpx;font-size:24rpx}.hint{text-align:center;color:#9ca3af;padding:40rpx}</style>